using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF9 changed the default discriminator property from "Discriminator" to "$type".
            // Preserve the old property name so existing 500K documents remain readable
            // and direct SQL queries referencing c.Discriminator keep working.
            entity.HasDiscriminator<string>("Discriminator");

            // EF9 changed the default id format from "EntityType|Key" to just "Key".
            // Preserve the old format so existing documents are still addressable.
            entity.HasIdProperty("id");
            entity.Property<string>("__id")
                  .ToJsonProperty("id");
            entity.HasPartitionKey(p => p.Id);
        });

        // EF9 Cosmos provider no longer supports HasIndex — Cosmos manages
        // indexing at the container level, not per-property.
        // Removed: entity.HasIndex(p => p.Sku);
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // Preserve EF8-style "EntityType|Key" id format for backward compatibility
        // with existing documents.
        configurationBuilder.Conventions.Add(_ =>
            new Microsoft.EntityFrameworkCore.Cosmos.Infrastructure.IdValueGeneratorConvention());
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

